import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.egate.generictabcontent import GenericTabContent


class InfoSim(GenericTabContent):
    """Infosim command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Infosim command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(InfoSim, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return "info_sim"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_line_epcsim_version(line)
                self._parse_line_compilation_date(line)
                self._parse_line_specification(line)
            except ParsingDone:
                pass
        return super(InfoSim, self).on_new_line(line, is_full_line)

    _re_epcsim_version = re.compile(r"Management\sGate\s\((?P<VERSION>[^)]+)\)", re.I)

    def _parse_line_epcsim_version(self, line):
        if self._regex_helper.search_compiled(InfoSim._re_epcsim_version, line):
            self.current_ret.update({"EPCSIM version": self._regex_helper.group("VERSION")})
            raise ParsingDone

    _re_compilation_date = re.compile(r"Compiled\son\s(?P<DATE>.+)", re.I)

    def _parse_line_compilation_date(self, line):
        if self._regex_helper.search_compiled(InfoSim._re_compilation_date, line):
            self.current_ret.update({"Compilation date": self._regex_helper.group("DATE")})
            raise ParsingDone

    _re_specification = re.compile(r"(?P<ATTR>[^:]+):\s(?P<VALUE>.*)")

    def _parse_line_specification(self, line):
        if self._regex_helper.search_compiled(InfoSim._re_specification, line):
            self.current_ret.update({self._regex_helper.group("ATTR"): self._regex_helper.group("VALUE")})
            raise ParsingDone


